from collections import deque


class EventLogger:
    """Collects and displays events generated by the simulation."""

    def __init__(self, debug=False, max_events=1000):
        self.debug = debug

        # Keep a bounded history for the future simulation dashboard.
        self.events = deque(maxlen=max_events)

    def log(
        self,
        sim_time,
        team_id,
        explorer_name,
        event,
        message,
        details=None,
        debug_only=False,
    ):
        """Record an event and optionally print it to the console."""

        entry = {
            "time": sim_time,
            "team_id": team_id,
            "explorer": explorer_name,
            "event": event,
            "message": message,
            "details": list(details or []),
            "debug_only": debug_only,
        }

        # Keep events even when they are hidden from normal console output.
        self.events.append(entry)

        # Debug-only events are printed only in debug mode.
        if debug_only and not self.debug:
            return entry

        print(
            f"[T={sim_time:6.1f}] "
            f"[TEAM {team_id}] "
            f"[{explorer_name}] "
            f"{event}"
        )

        print(f"    {message}")

        for detail in entry["details"]:
            print(f"    {detail}")

        return entry


    def get_recent_events(
        self,
        limit=20,
        team_id=None,
        explorer_name=None,
        include_debug=False,
    ):
        """Return recent events, optionally filtered."""

        filtered = [
            event
            for event in self.events
            if (
                include_debug or not event.get("debug_only", False)
            )
            and (
                team_id is None
                or event["team_id"] == team_id
            )
            and (
                explorer_name is None
                or event["explorer"] == explorer_name
            )
        ]

        return filtered[-limit:]